/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Solution {
    public int minimumFlips(TreeNode root, boolean result) {
        // iterative post-order: cost[node] = {flips to make false, flips to make true}
        List<TreeNode> order = new ArrayList<>();
        ArrayDeque<TreeNode> st = new ArrayDeque<>();
        st.push(root);
        while (!st.isEmpty()) {
            TreeNode t = st.pop();
            order.add(t);
            if (t.left != null) st.push(t.left);
            if (t.right != null) st.push(t.right);
        }
        Map<TreeNode, int[]> cost = new HashMap<>();
        for (int i = order.size() - 1; i >= 0; i--) {
            TreeNode t = order.get(i);
            int[] c;
            if (t.left == null && t.right == null) {
                c = new int[]{t.val == 0 ? 0 : 1, t.val == 1 ? 0 : 1};
            } else if (t.val == 5) {
                int[] ch = cost.get(t.left != null ? t.left : t.right);
                c = new int[]{ch[1], ch[0]};
            } else {
                int[] l = cost.get(t.left), r = cost.get(t.right);
                if (t.val == 2) c = new int[]{l[0] + r[0], Math.min(l[1] + Math.min(r[0], r[1]), r[1] + Math.min(l[0], l[1]))};
                else if (t.val == 3) c = new int[]{Math.min(l[0] + Math.min(r[0], r[1]), r[0] + Math.min(l[0], l[1])), l[1] + r[1]};
                else c = new int[]{Math.min(l[0] + r[0], l[1] + r[1]), Math.min(l[0] + r[1], l[1] + r[0])};
            }
            cost.put(t, c);
        }
        return cost.get(root)[result ? 1 : 0];
    }
}
